// MnemoScn.cpp : Defines the initialization routines for the DLL.//#include "stdafx.h"#include "MnemoWnd.h"#include <algorithm>#include <string>#include "Synchronizer.h"#include "LogFile.h"//LRESULT CALLBACK MnemoProc( HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam );LRESULT CALLBACK TexnoProc( HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam );//CSynchronizer g_Synchronizer;//HINSTANCE g_hModule;BOOL g_bLocalConnection;///*#ifdef LINUXclass CMnemoWndApp : public CWinApp{public:	CMnemoWndApp();// Overridespublic:	virtual BOOL InitInstance();	DECLARE_MESSAGE_MAP()};BEGIN_MESSAGE_MAP(CMnemoWndApp, CWinApp)END_MESSAGE_MAP()CMnemoWndApp::CMnemoWndApp(){}CMnemoWndApp theApp;BOOL CMnemoWndApp::InitInstance(){	CWinApp::InitInstance();	g_hModule = m_hInstance;	return TRUE;}#else*/BOOL APIENTRY DllMain( HMODULE hModule, DWORD  reason, LPVOID lpReserved )  {  switch ( reason )    {    case DLL_PROCESS_ATTACH:      {      g_hModule = hModule;      //      WNDCLASS wcl;      // При CS_DBLCLKS проблемы при нажатиях на кнопках      wcl.style = CS_HREDRAW | CS_VREDRAW | CS_GLOBALCLASS | CS_CLASSDC;// | CS_DBLCLKS;      wcl.hInstance = hModule;      //      wcl.hIcon   = NULL;      wcl.hCursor = ::LoadCursor( NULL, IDC_ARROW);      wcl.lpszMenuName = NULL;      //      wcl.cbClsExtra = 0;      wcl.cbWndExtra = 8;      //      wcl.hbrBackground = NULL;//(HBRUSH)::GetStockObject(BLACK_BRUSH);      //      wcl.lpfnWndProc   = MnemoProc;      wcl.lpszClassName = CLASS_MNEMO;      if ( !::RegisterClass( &wcl ) )        {        // Это очень-очень плохо.        }      //      wcl.lpfnWndProc   = TexnoProc;      wcl.lpszClassName = CLASS_TEXNO;      if ( !::RegisterClass( &wcl ) )        {        // Это очень-очень плохо.        }	  CLogFile::Initialize ("MnemoWnd", TRUE, FALSE, "MnemoWnd.txt");      }    break;    case DLL_PROCESS_DETACH:      {      }    };  return TRUE;  }//#endif // LINUX//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Для работы мнемосхем//void mvaluef( char* dst, int dim, double src )  {  if ( src == DBL_MAX )    {    lstrcpy( dst, "RRR" );    return;    }  else  if ( dim == -1 )    {    if ( src > 0 )      sprintf_s( dst, 16, "%d%%", (int)(src+0.05) );    else      sprintf_s( dst, 16, "%d%%", (int)(src-0.05) );    return;    }  //  char text[16];  sprintf_s( text, 16,"%%.%df", dim );  sprintf_s( dst , 16, text   , src );  }//DWORD g_dwMnemoStyle = 0;bool IsMnemoStyle(DWORD dwFlag)  {  return (g_dwMnemoStyle & dwFlag) != 0;  }//DWORD GetMnemoStyle()  {  return g_dwMnemoStyle;  }//void SetMnemoStyle(DWORD dwMnemoStyle)  {  g_dwMnemoStyle = dwMnemoStyle;  }//DWORD MnemoStyleXOR(DWORD dwFlags)  {  g_dwMnemoStyle ^= dwFlags;  return g_dwMnemoStyle;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~std::string GetExe64Path(){	std::string strExePath=::GetExePath();	std::transform(strExePath.begin(), strExePath.end(),strExePath.begin(), ::toupper);	std::string strExe="\\SYSTEM\\EXE\\";	std::string strExe64="\\SYSTEM\\EXE_64\\";	size_t nFound=strExePath.find(strExe);	if (nFound != std::string::npos) 		strExePath.replace(nFound, strExe.length(),strExe64);	return strExePath;}BOOL ParserCmdLine(char* ptr,SCmdLine& cmd)  {  CModelInfo& model = ::ModelInfo();  //  DWORD dwMnemo = 0;// Q  cmd.bInstructor = false;  cmd.bSound      = true;  cmd.szHIS[0]    = 0;  cmd.bOnlyField  = false;  cmd.bFixFacePlate=false;  cmd.bCAMS=false;  cmd.bUserFromCmd=false;  cmd.bWindowModeFlex=false;  cmd.bAllowBigSchemas = false;  cmd.bUsualDisplay= false;  cmd.nMonitor0SpecNumber=0;  cmd.nProjectNumber=0;  cmd.bLocalPlaceFromCmd=false;#ifdef LINUX  CLogFile::LogEx (LOGLEVEL_LOW, "ParserCmdLine_1: ptr = %s", ptr);#endif // LINUX  //  // Определяем ключи программы  while ( *ptr )    {    while ( *ptr == ' ' ) ptr++;//Пропуск пробелов    char* str = ptr; //Поиск конца ключа    if ( *ptr == '"' ) //Если в имени есть пробел      {      ptr++;str++;      while ( *str && *str != '"' ) str++;//Идем до конца ключа      }    else      {      while ( *str && *str != ' ' ) str++;//Пропуск НЕпробелов      }    char ch = *str;    *str = '\0';    if ( *ptr == '/' || *ptr == '-' )      {      char key = toupper(ptr[1]);      ptr += 2;//Skip '/' & key              if ( *ptr == '"' ) //Если в имени есть пробел        {        ptr++;*str = ch;str = ptr;        while ( *str && *str != '"' ) str++;//Идем до конца ключа        ch = *str;        *str = '\0';        }      switch ( key )        {        case 'A':          cmd.bSound = *ptr != '-';          break;		case 'B':          cmd.bAllowBigSchemas = true;          break;        case 'C':          cmd.bCAMS = true;          break;		case 'D':			cmd.bDebugKirishiMonitorsInfo = true;          break;        case 'H':          cmd.szHIS[0] = 'H';          lstrcpy( cmd.szHIS+1, ptr );          ::CharUpper( cmd.szHIS );          break;        case 'I':          cmd.bInstructor = true;          break;        case 'F':          cmd.bOnlyField = true;//ключ командной строки -f           break;        case 'K':          cmd.bDisableKirishiView = true;          break;		case 'M':          sscanf_s( ptr, "%d", &cmd.nMonitor0SpecNumber );         break;	     case 'U':          cmd.bUsualDisplay = true;          break;	  	 case 'P':          sscanf_s( ptr, "%d", &cmd.nProjectNumber );         break;        case 'R':          cmd.bFixFacePlate = true;          break;	    case 'W':          cmd.bWindowModeFlex = true;          break;        case 'Q':          sscanf_s( ptr, "%x", &dwMnemo );          break;        case 'S':          strcpy_s( CPipeClient::ms_szServer, ptr );          break;        case 'O':          strcpy_s( CPipeClient::ms_szOperator, ptr );          cmd.bUserFromCmd=true;          break;        case 'L':          strcpy_s( CPipeClient::ms_szLockArea, ptr );		  cmd.bLocalPlaceFromCmd=true;          break;        case 'T':          if( *ptr )          {            USHORT port = atoi( ptr );            if( port > 1024 )              CPipeClient::ms_RemoteTcpPort = port;          }          CPipeClient::ms_bUsePipe = false;          CPipeClient::ms_bCopyNetworkFile = false;          break;        }      }    *str = ch;    ptr = str;    if ( !*ptr ) ptr--;// Чтобы не вылезти за пределы массива    ptr++;    }  //  // Если человеку разрешено настраивать PID-ы  // или изменять содержимое мнемосхем, то, наверное:  if ( dwMnemo & (MNEMO_EDIT|MNEMO_TEST) )    cmd.bInstructor = true;  //  ::SetMnemoStyle( dwMnemo );	// VM: Run synchronization here...  g_bLocalConnection = IsLocalConnection (CPipeClient::ms_bUsePipe, CPipeClient::ms_szServer);  BOOL bRunSynchr = !g_bLocalConnection;  if ( !bRunSynchr && CLogFile::IsLocalSyncEnabled () )	  bRunSynchr = TRUE;  BOOL bNewInstallation = IsNewInstallation ();  if ( bRunSynchr && bNewInstallation )	g_Synchronizer.Run (g_hModule, CPipeClient::ms_szServer);  // ...  // Сразу запускаем Сетевой Менеджер  if( lstrcmp( CPipeClient::ms_szServer, "." ) == 0 )  {    if( CPipeClient::ms_bUsePipe )    {      HWND hWnd = ::FindWindow( NAME_CLASS_SERVER, NULL );      if ( !::IsWindow( hWnd ) )	  {		  std::string strServerFileName=GetExe64Path();		  strServerFileName+="ServerEx.exe";#ifdef LINUX		  CLogFile::LogEx (LOGLEVEL_LOW, "WinExec: ServerEx.exe");#endif // LINUX		  ::WinExec( strServerFileName.c_str(), SW_SHOW );	  }    }    else    {      HWND hWnd = ::FindWindow( NAME_CLASS_SERVER_TCP, NULL );      if( !::IsWindow( hWnd ) )      {        char buf[64];        sprintf_s( buf, "ServerRsuTcp.exe -t%d", CPipeClient::ms_RemoteTcpPort );#ifdef LINUX		  CLogFile::LogEx (LOGLEVEL_LOW, "WinExec: ServerRsuTcp.exe");#endif // LINUX        ::WinExec( buf, SW_SHOW );      }    }  }  //    HWND hComm;	if( !IsKeySensor( hComm ) )    {        char str[128] = "keybsensor.exe";        if ( strcmp( CPipeClient::ms_szServer, "." ) )        {          strcat_s( str, " -s" );          strcat_s( str, CPipeClient::ms_szServer );        }#ifdef LINUX		  CLogFile::LogEx (LOGLEVEL_LOW, "WinExec: keybsensor.exe");#endif // LINUX		  ::WinExec( str, SW_HIDE );        ::WinExec( str, SW_SHOW );     }#ifdef LINUX  CLogFile::LogEx (LOGLEVEL_LOW, "ParserCmdLine_2: cmd.nMonitor0SpecNumber = %d", cmd.nMonitor0SpecNumber);#endif // LINUX  return TRUE;  }void GetStaffFilePath (char *szFile, int nSize){	g_Synchronizer.GetStaffFilePath (szFile, nSize);}